<?php require_once __DIR__.'/includes/permissions.php';require_permission('ocr.view');$rows=db()->query('SELECT o.*,u.full_name creator,v.full_name verifier FROM ocr_documents o LEFT JOIN users u ON u.id=o.created_by LEFT JOIN users v ON v.id=o.verified_by ORDER BY o.created_at DESC LIMIT 100')->fetchAll();include __DIR__.'/includes/header.php';?><div class="page-head"><div><h1>OCR Digitization</h1><p>Upload paper-record images, extract text, review and verify before any official record is created.</p></div></div><div class="alert alert-warning"><i class="bi bi-shield-exclamation"></i> OCR output is untrusted until a staff member reviews and verifies it. It is never automatically inserted into resident or medical records.</div><div class="panel mb-4"><div class="panel-head"><h5>Scan / Upload Paper Records</h5></div><form id="ocrForm" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="mb-3"><input type="file" id="ocrFiles" name="files[]" class="form-control" accept="image/jpeg,image/png,image/webp" multiple required><div class="form-text">JPG, PNG or WEBP. Maximum 5 files per upload, 5 MB each.</div></div><div id="ocrProgress"></div><button class="btn btn-primary" type="submit"><i class="bi bi-file-text"></i> Extract Text</button></form></div><div id="ocrResults"></div><div class="panel"><div class="panel-head"><h5>OCR History</h5></div><div class="table-responsive"><table class="table"><thead><tr><th>File</th><th>Status</th><th>Created</th><th>Verified By</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['file_name'])?></td><td><?=e($r['status'])?></td><td><?=e($r['created_at'])?></td><td><?=e($r['verifier']??'—')?></td></tr><?php endforeach;?></tbody></table></div></div><script src="https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js"></script><script>const form=document.getElementById('ocrForm'),filesEl=document.getElementById('ocrFiles'),progress=document.getElementById('ocrProgress'),results=document.getElementById('ocrResults');form.addEventListener('submit',async e=>{e.preventDefault();results.innerHTML='';if(filesEl.files.length>5){alert('Maximum 5 images per upload.');return;}for(const file of filesEl.files){const fd=new FormData();fd.append('csrf',form.csrf.value);fd.append('file',file);const r=await fetch('<?=BASE_URL?>/api/ocr.php',{method:'POST',body:fd});const j=await r.json();if(!j.success){results.insertAdjacentHTML('beforeend','<div class="alert alert-danger">'+j.message+'</div>');continue;}const card=document.createElement('div');card.className='panel mb-3';card.innerHTML='<div class="panel-head"><h5>'+file.name+'</h5><span class="badge text-bg-warning">Review Required</span></div><textarea class="form-control ocr-text" rows="10"></textarea><div class="mt-3 d-flex gap-2"><button class="btn btn-success verify">Verify & Save OCR Text</button><button class="btn btn-outline-danger reject">Reject</button></div>';results.appendChild(card);const ta=card.querySelector('textarea');const status=card.querySelector('.badge');const worker=await Tesseract.createWorker('eng');const out=await worker.recognize(file);ta.value=out.data.text;await worker.terminate();await fetch('<?=BASE_URL?>/api/ocr.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf:form.csrf.value,action:'update',id:j.id,extracted_text:ta.value})});card.querySelector('.verify').onclick=async()=>{const rr=await fetch('<?=BASE_URL?>/api/ocr.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf:form.csrf.value,action:'verify',id:j.id,extracted_text:ta.value})});const jj=await rr.json();status.textContent=jj.success?'Verified':'Error';status.className='badge text-bg-'+(jj.success?'success':'danger');};card.querySelector('.reject').onclick=async()=>{const rr=await fetch('<?=BASE_URL?>/api/ocr.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf:form.csrf.value,action:'reject',id:j.id})});const jj=await rr.json();if(jj.success){status.textContent='Rejected';status.className='badge text-bg-danger';}};}progress.innerHTML='';});</script><?php include __DIR__.'/includes/footer.php'; ?>
